const TOOL_NAME = 'text_transform';
const MODES = ['uppercase', 'lowercase', 'slug'];
const ALLOWED_KEYS = new Set(['text', 'mode', 'trim']);

const TOOL_DEFINITION = {
  name: TOOL_NAME,
  description: 'Transform a text string using the chosen mode.',
  inputSchema: {
    type: 'object',
    properties: {
      text: {
        type: 'string',
        description: 'The input text to transform.'
      },
      mode: {
        type: 'string',
        enum: MODES,
        description: 'The transformation mode to apply.'
      },
      trim: {
        type: 'boolean',
        description: 'Whether to trim leading/trailing whitespace before transforming.',
        default: true
      }
    },
    required: ['text', 'mode'],
    additionalProperties: false
  }
};

function validateArgs(args) {
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Arguments must be an object.');
  }

  for (const key of Object.keys(args)) {
    if (!ALLOWED_KEYS.has(key)) {
      throw new Error(`Unknown argument: ${key}`);
    }
  }

  if (!Object.prototype.hasOwnProperty.call(args, 'text')) {
    throw new Error('Missing required argument: text');
  }
  if (!Object.prototype.hasOwnProperty.call(args, 'mode')) {
    throw new Error('Missing required argument: mode');
  }

  if (typeof args.text !== 'string') {
    throw new Error('Argument "text" must be a string.');
  }
  if (typeof args.mode !== 'string') {
    throw new Error('Argument "mode" must be a string.');
  }
  if (!MODES.includes(args.mode)) {
    throw new Error(`Argument "mode" must be one of: ${MODES.join(', ')}.`);
  }

  let trim = true;
  if (Object.prototype.hasOwnProperty.call(args, 'trim')) {
    if (typeof args.trim !== 'boolean') {
      throw new Error('Argument "trim" must be a boolean.');
    }
    trim = args.trim;
  }

  return { text: args.text, mode: args.mode, trim };
}

function slugify(text) {
  const lowered = text.toLowerCase();
  const hyphenated = lowered.replace(/[^a-z0-9]+/g, '-');
  return hyphenated.replace(/^-+|-+$/g, '');
}

function transform({ text, mode, trim }) {
  if (mode === 'slug') {
    // Slug mode must trim, lowercase, replace non-alnum runs, and strip edge hyphens.
    return slugify(trim ? text.trim() : text);
  }

  const prepared = trim ? text.trim() : text;
  if (mode === 'uppercase') return prepared.toUpperCase();
  if (mode === 'lowercase') return prepared.toLowerCase();
  // Unreachable due to validation, but keeps the function total.
  throw new Error(`Unsupported mode: ${mode}`);
}

export async function listTools() {
  return [TOOL_DEFINITION];
}

export async function callTool(name, args) {
  if (name !== TOOL_NAME) {
    throw new Error(`Unknown tool: ${name}`);
  }
  const validated = validateArgs(args);
  const result = transform(validated);
  return { content: [{ type: 'text', text: result }] };
}

