import('./server.mjs').then(async ({listTools, callTool}) => {
  console.log('--- listTools ---');
  console.log(JSON.stringify(await listTools(), null, 2));

  const checks = [
    ['uppercase basic',  {text:'  Hello  ', mode:'uppercase'}, 'HELLO'],
    ['uppercase no trim',{text:'  Hello  ', mode:'uppercase', trim:false}, '  HELLO  '],
    ['lowercase basic',  {text:'WORLD',     mode:'lowercase'}, 'world'],
    ['slug basic',       {text:' Hello, MCP! ', mode:'slug'}, 'hello-mcp'],
    ['slug multiple punct', {text:'  ___Foo!! Bar??Baz***  ', mode:'slug'}, 'foo-bar-baz'],
    ['slug edge hyphens', {text:'---hello---', mode:'slug'}, 'hello'],
    ['slug empty',       {text:'   ', mode:'slug'}, ''],
    ['slug numbers',     {text:'Item 42: New!', mode:'slug'}, 'item-42-new'],
  ];

  for (const [name, args, expected] of checks) {
    try {
      const r = await callTool('text_transform', args);
      const ok = r.content[0].text === expected;
      console.log((ok?'PASS':'FAIL'), name, '=>', JSON.stringify(r.content[0].text), ok?'':'(expected '+JSON.stringify(expected)+')');
    } catch (e) {
      console.log('FAIL', name, '=> threw', e.message);
    }
  }

  const rejections = [
    ['unknown tool',     () => callTool('nope', {text:'x', mode:'uppercase'})],
    ['missing text',     () => callTool('text_transform', {mode:'uppercase'})],
    ['missing mode',     () => callTool('text_transform', {text:'x'})],
    ['bad mode',         () => callTool('text_transform', {text:'x', mode:'title'})],
    ['text not string',  () => callTool('text_transform', {text:123, mode:'uppercase'})],
    ['trim not bool',    () => callTool('text_transform', {text:'x', mode:'uppercase', trim:'yes'})],
    ['extra prop',       () => callTool('text_transform', {text:'x', mode:'uppercase', extra:1})],
    ['null args',        () => callTool('text_transform', null)],
  ];

  for (const [name, fn] of rejections) {
    try {
      const r = await fn();
      console.log('FAIL', name, '=> should have thrown, got', JSON.stringify(r));
    } catch (e) {
      console.log('PASS', name, '=> rejected:', e.message);
    }
  }
});
""}

